-- LabMitra: full test catalogue from the BYOS Lab Test Portfolio (598 tests).
-- Run once in Supabase SQL Editor. Safe to re-run: tests already imported are skipped, and your edited prices are never overwritten.
--
-- What it does:
--   1. Adds three columns to tests:  trending (shown on the home page), code (Sr. No. in the BYOS list), tat_minutes (report time, for sorting).
--   2. Marks the tests you already have as trending, so the home page stays exactly as it is.
--   3. Links those tests to the same test in the BYOS list, so they are not listed twice (your prices are kept).
--   4. Imports the rest. Price = MRP from the BYOS list minus ₹1 (e.g. 1300 → 1299); change any price in Admin › Test Pricing.

alter table tests add column if not exists trending boolean not null default false;
alter table tests add column if not exists code int;
alter table tests add column if not exists tat_minutes int;
create unique index if not exists tests_code_key on tests(code);

do $$ begin
  if not exists (select 1 from tests where trending) then update tests set trending=true where code is null; end if;
end $$;

update tests set code=196,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Complete Blood Count (CBC)' and not exists (select 1 from tests where code=196);
update tests set code=521,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Thyroid Profile (T3, T4, TSH)' and not exists (select 1 from tests where code=521);
update tests set code=5,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Vitamin D (25-OH)' and not exists (select 1 from tests where code=5);
update tests set code=380,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Liver Function Test (LFT)' and not exists (select 1 from tests where code=380);
update tests set code=367,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Kidney Function Test (KFT)' and not exists (select 1 from tests where code=367);
update tests set code=281,tat_minutes=coalesce(tat_minutes,120) where code is null and name='HbA1c' and not exists (select 1 from tests where code=281);
update tests set code=389,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Lipid Profile' and not exists (select 1 from tests where code=389);
update tests set code=577,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Vitamin B12' and not exists (select 1 from tests where code=577);
update tests set code=571,tat_minutes=coalesce(tat_minutes,120) where code is null and name='Urine Routine & Microscopy' and not exists (select 1 from tests where code=571);

on conflict (code) do nothing;
